entries=[]
for line in raw.splitlines():
    num,name,cl,stamp,contain,desc,log1,log2=line.split('|')
    n=int(num); ident=f'{n:03d}'
    entries.append(dict(id=ident,itemNumber=f'SCP-{ident}',name=name,objectClass=cl,stamp=stamp,containment=contain,description=desc,incidentHistory=[dict(date='19██ · INITIAL RECORD',text=log1),dict(date='20██ · REVIEW ADDENDUM',text=log2)],icon=f'assets/{ident}.svg',capability=f'assets/{ident}-capability.svg',source=f'https://scp-wiki.wikidot.com/scp-{n:03d}'))
    shape=shapes[num]
    for capability in [False,True]:
        color={'Safe':'#98ac85','Euclid':'#c0ae77','Keter':'#ba7760','Thaumiel':'#b0b7ae'}[cl]
        # The capability plates use original symbolic operational overlays and animated specimen silhouettes.
        mode={'173':'blink','096':'distress','682':'regen','106':'phase','999':'bounce','3008':'drift'}.get(num,'breathe')
        animations={'blink':'0%,44%,54%,100%{transform:translateX(0)}45%,53%{transform:translateX(45px)}','distress':'0%,100%{transform:translateY(0)}50%{transform:translateY(4px) rotate(1deg)}','regen':'0%,100%{filter:brightness(.7)}50%{filter:brightness(1.4)}','phase':'0%,100%{opacity:.9}50%{opacity:.2;transform:translateY(15px)}','bounce':'0%,100%{transform:translateY(0) scaleY(1)}50%{transform:translateY(-17px) scaleY(1.06)}','drift':'0%,100%{transform:scale(1)}50%{transform:scale(1.12)}','breathe':'0%,100%{opacity:.75}50%{opacity:1}'}
        anim=f'<style>.specimen{{transform-origin:240px 240px;animation:activity 5s ease-in-out infinite}}@keyframes activity{{{animations[mode]}}}@media(prefers-reduced-motion:reduce){{.specimen{{animation:none}}}}</style>' if capability else ''
        overlay=f'<path d="M25 180h65m300 0h65M240 45v30m0 225v25" stroke="{color}" opacity=".7"/><rect x="28" y="308" width="424" height="29" fill="#14211b"/><text x="40" y="327" font-family="monospace" font-size="11" fill="{color}">BEHAVIORAL MODEL / {mode.upper()} / LOOP</text>' if capability else ''
        svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 360" role="img" aria-label="Original illustrated containment study of SCP-{ident}">{anim}<defs><radialGradient id="room"><stop stop-color="#626b58"/><stop offset="1" stop-color="#192822"/></radialGradient><filter id="grain"><feTurbulence baseFrequency=".7" numOctaves="3" seed="{n}"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".16"/></feComponentTransfer><feBlend in="SourceGraphic" mode="soft-light"/></filter><pattern id="scan" width="4" height="4" patternUnits="userSpaceOnUse"><path d="M0 0h4" stroke="#060f0c" opacity=".2"/></pattern></defs><rect width="480" height="360" fill="#101b16"/><g filter="url(#grain)"><path d="M30 20h420v300H30z" fill="url(#room)"/><path d="M30 20l68 58h284l68-58M98 78v202l-68 40m352-242v202l68 40M98 280h284" fill="none" stroke="#82917b" opacity=".2"/><path d="M143 58h194" stroke="#c0c9a8" stroke-width="5" opacity=".6"/><ellipse cx="240" cy="284" rx="120" ry="18" fill="#101b15" opacity=".6"/><g class="specimen">{shape}</g></g>{overlay}<rect width="480" height="360" fill="url(#scan)"/><path d="M18 45V18h27m390 0h27v27M18 315v27h27m390 0h27v-27" stroke="#9da78b" opacity=".55" fill="none"/><text x="30" y="42" font-size="12" font-family="monospace" fill="#c0bfa4">{('SIMULATION' if capability else 'RECORD')} / {ident}</text><circle cx="414" cy="37" r="4" fill="#b5785f"/><text x="30" y="347" font-size="10" font-family="monospace" fill="#a9b098">SITE RECORDS · ILLUSTRATED PLATE / NO OPTICAL FEED</text></svg>'''
        (ROOT/'assets'/f'{ident}{"-capability" if capability else ""}.svg').write_text(svg)
(ROOT/'data.json').write_text(json.dumps(entries,indent=2,ensure_ascii=False))
print('Created',len(entries),'dossiers and',len(entries)*2,'original SVG assets')

